def tests(stems): return [t.strip() for t in re.split(r";\s*", stems) if t.strip() and t.strip() != "-"]
def counts(stems):
    pos = neg = 0; miss = []
    for t in tests(stems):
        p = TF.get(t)
        if p is None: miss.append(t); continue
        tx = p.read_text(); pos += len(re.findall(r"^\s*def test_", tx, re.M)); neg += len(re.findall(r"assertRaises|assertEqual\(code\(|Refusal|IntegrityFailure", tx))
    return pos, neg, miss
